static GtkWidget *window,*chat,*input,*status_label,*send_button,*endpoint_entry;
static std::mutex qmutex; static std::queue<std::function<void()>> q;
static bool busy=false; static std::string endpoint="http://127.0.0.1:8080";
static void post_ui(std::function<void()> fn){ {std::lock_guard<std::mutex> l(qmutex);q.push(std::move(fn));} g_main_context_invoke(nullptr,[](gpointer)->gboolean{std::queue<std::function<void()>> local;{std::lock_guard<std::mutex> l(qmutex);std::swap(local,q);}while(!local.empty()){local.front()();local.pop();}return G_SOURCE_REMOVE;},nullptr);}
static std::string esc(const std::string&s){std::string o;for(unsigned char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c>=32)o+=(char)c;}}return o;}
static size_t write_data(char*p,size_t s,size_t n,void*u){static_cast<std::string*>(u)->append(p,s*n);return s*n;}
static void bubble(const std::string&t,bool user){GtkWidget*r=gtk_box_new(GTK_ORIENTATION_VERTICAL,4);gtk_widget_set_margin_start(r,18);gtk_widget_set_margin_end(r,18);gtk_widget_set_margin_top(r,8);gtk_widget_set_margin_bottom(r,8);GtkWidget*l=gtk_label_new(t.c_str());gtk_label_set_wrap(GTK_LABEL(l),TRUE);gtk_label_set_selectable(GTK_LABEL(l),TRUE);gtk_label_set_xalign(GTK_LABEL(l),0);gtk_label_set_yalign(GTK_LABEL(l),0);gtk_widget_set_hexpand(l,TRUE);gtk_widget_add_css_class(l,user?"user-bubble":"dragon-bubble");gtk_box_append(GTK_BOX(r),l);gtk_list_box_append(GTK_LIST_BOX(chat),r);}
static void send_message(){if(busy)return;GtkTextBuffer*b=gtk_text_view_get_buffer(GTK_TEXT_VIEW(input));GtkTextIter a,z;gtk_text_buffer_get_bounds(b,&a,&z);gchar*raw=gtk_text_buffer_get_text(b,&a,&z,FALSE);std::string prompt=raw?raw:"";g_free(raw);if(prompt.empty())return;gtk_text_buffer_set_text(b,"",-1);bubble(prompt,true);busy=true;gtk_widget_set_sensitive(send_button,FALSE);gtk_label_set_text(GTK_LABEL(status_label),"Conectando à Cassandra…");const char*ep=gtk_editable_get_text(GTK_EDITABLE(endpoint_entry));endpoint=(ep&&*ep)?ep:"http://127.0.0.1:8080";while(!endpoint.empty()&&endpoint.back()=='/')endpoint.pop_back();std::thread([prompt]{std::string response;CURL*c=curl_easy_init();if(c){std::string url=endpoint+"/api/chat",body="{\"message\":\""+esc(prompt)+"\",\"thinking\":false}";curl_slist*h=nullptr;h=curl_slist_append(h,"Content-Type: application/json");curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_HTTPHEADER,h);curl_easy_setopt(c,CURLOPT_POSTFIELDS,body.c_str());curl_easy_setopt(c,CURLOPT_POSTFIELDSIZE,(long)body.size());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_data);curl_easy_setopt(c,CURLOPT_WRITEDATA,&response);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,5L);curl_easy_setopt(c,CURLOPT_TIMEOUT,300L);CURLcode rc=curl_easy_perform(c);long code=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&code);if(rc!=CURLE_OK)response=std::string("Falha de conexão: ")+curl_easy_strerror(rc)+". Confira se o backend está rodando.";else if(code<200||code>=300)response="A API retornou HTTP "+std::to_string(code)+". Confira o backend.";curl_slist_free_all(h);curl_easy_cleanup(c);}else response="Não foi possível inicializar libcurl.";if(response.empty())response="A Cassandra encerrou a resposta sem conteúdo.";post_ui([response]{bubble(response,false);busy=false;gtk_widget_set_sensitive(send_button,TRUE);gtk_label_set_text(GTK_LABEL(status_label),"Resposta concluída");});}).detach();}
static void on_send(GtkButton*,gpointer){send_message();}
static gboolean on_key(GtkEventControllerKey*,guint keyval,guint,GdkModifierType state,gpointer){if(keyval==GDK_KEY_Return&&(state&GDK_CONTROL_MASK)){send_message();return TRUE;}return FALSE;}
static const char*css=R"CSS(window{background:#090b14;color:#edf0ff}.sidebar{background:#101321;border-right:1px solid #252943}.brand{color:#c5a6ff;font-size:24px;font-weight:800;letter-spacing:5px}.muted{color:#929bbd}.section-title{color:#f2efff;font-size:25px;font-weight:750}.nav-item{color:#b7c0e0;padding:12px 14px;border-radius:10px}.nav-active{background:#29224e;color:#cbb4ff;font-weight:700}.dragon-bubble{background:#191e31;color:#f0f1ff;padding:16px;border-radius:4px 14px 14px 14px}.user-bubble{background:#282443;color:#f7f2ff;padding:16px;border-radius:14px 4px 14px 14px}.entry-area{background:#141829;border:1px solid #8d72f9;border-radius:14px;padding:8px}button.send{background:#9a7aff;color:#100d21;border-radius:12px;padding:12px 18px;font-weight:800}.status{color:#65dfa0;font-size:12px}.context{background:#0e1220;border-left:1px solid #252943;padding:18px})CSS";
